const t = $json || {};
const ex = t.execution || {};
const wf = t.workflow || {};
const err = ex.error || {};
const wfName = wf.name || 'unknown workflow';
const wfId = wf.id != null ? String(wf.id) : null;
const execId = ex.id != null ? String(ex.id) : null;
const execUrl = ex.url || null;
const lastNode = ex.lastNodeExecuted || '(unknown node)';
const errName = err.name || 'Error';
const errMsg = (err.message != null ? String(err.message) : 'no message').slice(0, 900);
const mode = ex.mode || '';

// cart_id stays null on purpose. The Error Trigger payload carries execution and
// workflow metadata only - it does not expose the item that was in flight, so any
// cart id written here would be a guess. The execution URL is the honest link back
// to the failing run, and the run_logs row is findable by execution_id.
const run_log = {
  workflow_name: wfName,
  execution_id: execId,
  cart_id: null,
  status: 'failed',
  step_name: 'workflow_error',
  error_message: (errName + ': ' + errMsg).slice(0, 1000),
  metadata: {
    case: 'case-2',
    last_node: lastNode,
    error_name: errName,
    mode: mode,
    workflow_id: wfId,
    execution_url: execUrl
  }
};

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Workflow failure - Case 2 (abandoned cart)', emoji: false } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Workflow:*\n' + wfName },
    { type: 'mrkdwn', text: '*Failed node:*\n' + lastNode },
    { type: 'mrkdwn', text: '*Error type:*\n' + errName },
    { type: 'mrkdwn', text: '*Execution:*\n' + (execId || '-') }
  ]},
  { type: 'section', text: { type: 'mrkdwn', text: '*Message:*\n```' + errMsg + '```' } }
];
if (execUrl) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '<' + execUrl + '|Open execution>' }] });

const slack_body = {
  channel: '#automation-errors',
  text: 'Case 2 workflow failure in ' + wfName + ' (' + errName + ')',
  blocks: blocks
};

return [{ json: { run_log, slack_body } }];
